const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json;
  const lines = String(j.action_items || '')
    .split('\n')
    .map((l) => l.replace(/^\s*[-*\u2022]\s*/, '').trim())
    .filter((l) => l.length > 0);
  if (lines.length === 0) {
    out.push({ json: { incident_id: j.incident_id || '', incident_title: j.incident_title || '', item_text: 'No action items', owner: '', due_date: '', status: 'OPEN', reporter_email: j.reporter_email || '', created_at: j.received_at || '' } });
  } else {
    for (const line of lines) {
      let owner = '';
      let due = '';
      const mO = line.match(/owner:\s*([^|]+)/i);
      const mD = line.match(/due:\s*(\d{4}-\d{2}-\d{2})/i);
      if (mO) { owner = mO[1].trim(); }
      if (mD) { due = mD[1].trim(); }
      out.push({ json: { incident_id: j.incident_id || '', incident_title: j.incident_title || '', item_text: line, owner: owner, due_date: due, status: 'OPEN', reporter_email: j.reporter_email || '', created_at: j.received_at || '' } });
    }
  }
}
return out;

const items = $input.all();
const now = Date.now();
const open = items.filter((i) => String(i.json.status || '').toUpperCase() === 'OPEN');
if (open.length === 0) {
  return [{ json: { no_open: true } }];
}
const out = [];
for (const it of open) {
  const j = it.json;
  let is_overdue = false;
  let due = String(j.due_date || '').trim();
  if (due) {
    const d = new Date(due);
    if (!isNaN(d.getTime()) && d.getTime() < now) { is_overdue = true; }
  }
  out.push({
    json: {
      incident_id: j.incident_id || '',
      incident_title: j.incident_title || '',
      item_text: j.item_text || '',
      owner: j.owner || '',
      due_date: due,
      status: 'OPEN',
      reporter_email: j.reporter_email || '',
      is_overdue: is_overdue,
      line: (j.incident_title || '') + ' | ' + (j.item_text || '') + ' | Owner: ' + (j.owner || 'n/a') + ' | Due: ' + (due || 'n/a') + (is_overdue ? ' | OVERDUE' : '')
    }
  });
}
return out;

const items = $input.all();
const now = new Date();
const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
const filtered = items.filter((it) => {
  const ts = new Date(it.json.created_at || 0).getTime();
  return !isNaN(ts) && ts >= firstOfMonth;
});
return filtered;
